themes.css:
/* Slate — clean and professional: every section is a tidy panel on a soft grey page, like a well-kept profile.

   RULES (npm run check-themes enforces them):
   1. Scope EVERY selector under [data-style="slate"].  2. Define BOTH colour modes.  3. Name @keyframes "slate-…". */

:root[data-style="slate"] {
  --font-display: 'Inter', system-ui, sans-serif; --font-body: 'Inter', system-ui, sans-serif;
  --radius: 14px; --radius-sm: 8px; --radius-pill: 7px; --maxw: 920px; --card-pad: 1.15rem; --section-pad: 0px;
}
:root[data-style="slate"][data-mode="light"] {
  --bg: #eceff4; --bg-alt: #eceff4; --surface: #ffffff; --surface-2: #f3f5f9; --border: #dbe0e9;
  --text: #2b3340; --text-2: #525d70; --heading: #0f1722; --accent: #1f5fe0; --accent-ink: #ffffff;
}
:root[data-style="slate"][data-mode="dark"] {
  --bg: #0e1217; --bg-alt: #0e1217; --surface: #161b22; --surface-2: #1c222b; --border: #262e3a;
  --text: #c3ccd9; --text-2: #97a3b6; --heading: #f1f4f9; --accent: #6ea1ff; --accent-ink: #07121f;
}

/* chrome */
[data-style="slate"] body { font-size: .97rem; line-height: 1.6; }
[data-style="slate"] .site-nav { background: var(--surface); backdrop-filter: none; }
[data-style="slate"] .brand-mark { border-radius: 7px; }
[data-style="slate"] .brand-name { font-weight: 650; letter-spacing: -.01em; }
[data-style="slate"] .nav-links a { font-weight: 500; font-size: .86rem; }
[data-style="slate"] .btn { border-radius: var(--radius-sm); font-weight: 600; }
[data-style="slate"] .social { border-radius: var(--radius-sm); background: var(--surface-2); border-color: transparent; }

/* the signature: every block of the page is a panel */
[data-style="slate"] main { max-width: var(--maxw); margin: 1.25rem auto 0; padding: 0 1rem; display: grid; gap: 1rem; }
[data-style="slate"] .hero, [data-style="slate"] .section, [data-style="slate"] .section:nth-of-type(even) {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 0;
}
[data-style="slate"] .hero-inner, [data-style="slate"] .section-inner { max-width: none; padding: 1.7rem 1.8rem; }
[data-style="slate"] .sec-title { font-size: 1.12rem; font-weight: 700; letter-spacing: -.01em; margin-bottom: 1.2rem; padding-bottom: .8rem; border-bottom: 1px solid var(--border); }

/* hero reads like a profile header */
@media (min-width: 821px) {
  [data-style="slate"] .hero-inner { grid-template-columns: 168px minmax(0, 1fr); gap: 1.8rem; align-items: start; }
  [data-style="slate"] .hero-photo { order: -1; justify-self: start; width: 168px; max-width: none; aspect-ratio: 1; border-radius: 16px; }
}
[data-style="slate"] .hero { padding-top: 0; padding-bottom: 0; }
[data-style="slate"] .hero-photo { border: 1px solid var(--border); }
[data-style="slate"] .hero-name { font-size: clamp(2rem, 5vw, 2.7rem); font-weight: 700; letter-spacing: -.03em; }
[data-style="slate"] .hero-role { margin-top: .35rem; color: var(--text-2); font-weight: 500; font-size: 1.1rem; }
[data-style="slate"] .hero-bio { margin-top: .9rem; font-size: 1rem; max-width: 62ch; }
[data-style="slate"] .hero-kicker { margin: 0 0 .5rem; font-size: .88rem; }
[data-style="slate"] .hero-stats { margin-top: 1.2rem; padding-top: 1.1rem; border-top: 1px solid var(--border); gap: 1rem 2.2rem; }
[data-style="slate"] .hero-stats dd { font-size: 1.5rem; font-weight: 700; }
[data-style="slate"] .hero-cta { margin-top: 1.3rem; }

/* inner cards are quieter than the panels around them */
[data-style="slate"] .proj-card, [data-style="slate"] .edu-item, [data-style="slate"] .cert-card, [data-style="slate"] .award,
[data-style="slate"] .link-card, [data-style="slate"] .pub, [data-style="slate"] .contact-form { background: var(--surface-2); border-color: var(--border); box-shadow: none; }
[data-style="slate"] a.cert-card:hover, [data-style="slate"] a.award:hover, [data-style="slate"] a.link-card:hover, [data-style="slate"] a.pub:hover { border-color: var(--accent-text); text-decoration: none; }
[data-style="slate"] .proj-card { transition: border-color .15s; } [data-style="slate"] .proj-card:hover { border-color: var(--accent-text); }
[data-style="slate"] .chip { background: var(--surface-2); border-color: var(--border); }
[data-style="slate"] .tags li { background: var(--surface); border: 1px solid var(--border); color: var(--text-2); font-weight: 500; }
[data-style="slate"] .badge { background: var(--accent-soft); border-color: transparent; color: var(--accent-text); font-weight: 600; }
[data-style="slate"] .tl-item::before, [data-style="slate"] .section:nth-of-type(even) .tl-item::before { box-shadow: 0 0 0 4px var(--surface); }
[data-style="slate"] .timeline { border-left-color: var(--border); }
[data-style="slate"] .tl-role { font-size: 1.05rem; font-weight: 650; }
[data-style="slate"] .link-icon, [data-style="slate"] .ci-icon { border-radius: var(--radius-sm); }
[data-style="slate"] .cert-logo, [data-style="slate"] .edu-logo { border-radius: var(--radius-sm); }
[data-style="slate"] .contact-form input, [data-style="slate"] .contact-form textarea { background: var(--surface); }
[data-style="slate"] .site-footer { border-top: 0; margin-top: 1rem; }
@media (max-width: 600px) { [data-style="slate"] .hero-inner, [data-style="slate"] .section-inner { padding: 1.3rem 1.15rem; } [data-style="slate"] main { padding: 0 .6rem; } }

/* Aurora — glowing, technical, dark-first */
:root[data-style="aurora"] {
  --font-display: 'Syne', system-ui, sans-serif; --font-body: 'DM Sans', system-ui, sans-serif; --font-mono: 'DM Mono', ui-monospace, monospace;
  --radius: 18px; --radius-sm: 10px; --card-pad: 1.5rem;
}
:root[data-style="aurora"][data-mode="dark"] {
  --bg: #070b12; --bg-alt: #0a1019; --surface: #0f1722; --surface-2: #152131; --border: rgba(160, 190, 230, .12);
  --text: #b6c3d8; --text-2: #8191a9; --heading: #f2f6fc; --accent: #2ad4ff; --accent-ink: #03141c; --accent-text: var(--accent);
  --glow: color-mix(in srgb, var(--accent) 22%, transparent);
}
:root[data-style="aurora"][data-mode="light"] {
  --bg: #f3f6fb; --bg-alt: #e9eff7; --surface: #ffffff; --surface-2: #e4ecf6; --border: #d3deec;
  --text: #34445b; --text-2: #5d6e87; --heading: #0d1b2e; --accent: #0b6fd6; --accent-ink: #ffffff; --accent-text: var(--accent);
  --glow: color-mix(in srgb, var(--accent) 18%, transparent);
}
[data-style="aurora"] body { background: var(--bg); }
[data-style="aurora"] .hero { position: relative; overflow: hidden; isolation: isolate; }
[data-style="aurora"] .hero::before {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background-image: linear-gradient(var(--border) 1px, transparent 1px), linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 56px 56px; opacity: .55;
  -webkit-mask-image: radial-gradient(ellipse 70% 75% at 70% 40%, #000 20%, transparent 75%); mask-image: radial-gradient(ellipse 70% 75% at 70% 40%, #000 20%, transparent 75%);
}
[data-style="aurora"] .hero::after {
  content: ''; position: absolute; z-index: -1; width: 640px; height: 640px; right: -140px; top: -160px; border-radius: 50%;
  background: radial-gradient(circle, var(--glow), transparent 68%);
}
[data-style="aurora"] .hero-name { font-weight: 800; letter-spacing: -.035em; }
[data-style="aurora"] .hero-role { font-family: var(--font-mono); font-size: 1.05rem; font-weight: 400; }
[data-style="aurora"] .hero-role::before { content: '> '; opacity: .6; }
[data-style="aurora"] .hero-photo {
  padding: 3px; border-radius: 26px; background: linear-gradient(145deg, var(--accent), transparent 55%, var(--accent));
  box-shadow: 0 30px 80px -30px var(--glow);
}
[data-style="aurora"] .hero-photo img, [data-style="aurora"] .hero-photo--mono { border-radius: 23px; }
[data-style="aurora"] .hero-photo--mono { background: var(--surface); }
[data-style="aurora"] .hero-photo:not(.hero-photo--mono) img { background: var(--surface); }
[data-style="aurora"] .badge { font-family: var(--font-mono); font-size: .74rem; background: var(--surface); }
[data-style="aurora"] .btn--primary { box-shadow: 0 8px 28px -8px var(--accent); }
[data-style="aurora"] .nav-links a { font-family: var(--font-mono); font-size: .78rem; letter-spacing: .02em; }
[data-style="aurora"] .section:nth-of-type(even) { background: var(--bg-alt); }
[data-style="aurora"] .sec-title { font-weight: 800; display: flex; align-items: center; gap: 1rem; }
[data-style="aurora"] .sec-title::after { content: ''; flex: 1; max-width: 160px; height: 2px; background: linear-gradient(90deg, var(--accent), transparent); }
[data-style="aurora"] .proj-card, [data-style="aurora"] .edu-item, [data-style="aurora"] .cert-card, [data-style="aurora"] .award, [data-style="aurora"] .link-card, [data-style="aurora"] .pub, [data-style="aurora"] .contact-form { transition: border-color .2s, box-shadow .2s, transform .2s; }
[data-style="aurora"] .proj-card:hover, [data-style="aurora"] a.cert-card:hover, [data-style="aurora"] a.award:hover, [data-style="aurora"] a.link-card:hover, [data-style="aurora"] a.pub:hover { border-color: var(--accent); box-shadow: 0 18px 50px -24px var(--glow); transform: translateY(-3px); text-decoration: none; }
[data-style="aurora"] .tl-item::before { box-shadow: 0 0 0 4px var(--bg), 0 0 16px var(--accent); }
[data-style="aurora"] .section:nth-of-type(even) .tl-item::before { box-shadow: 0 0 0 4px var(--bg-alt), 0 0 16px var(--accent); }
[data-style="aurora"] .timeline { border-left-color: color-mix(in srgb, var(--accent) 35%, var(--border)); }
[data-style="aurora"] .tl-period, [data-style="aurora"] .pub-year, [data-style="aurora"] .ci-label { font-family: var(--font-mono); }
[data-style="aurora"] .chip { background: var(--surface); }
[data-style="aurora"] .chip--skill:hover { border-color: var(--accent); }

/* Folio — quiet, typographic; the name stays pinned in a sidebar */
:root[data-style="folio"] {
  --font-display: 'Instrument Serif', Georgia, serif; --font-body: 'Instrument Sans', system-ui, sans-serif; --font-mono: ui-monospace, monospace;
  --radius: 4px; --radius-sm: 3px; --radius-pill: 3px; --maxw: 980px; --card-pad: 1.3rem; --section-pad: clamp(3rem, 6vw, 5rem);
}
:root[data-style="folio"][data-mode="light"] {
  --bg: #f6f7f9; --bg-alt: #f6f7f9; --surface: #ffffff; --surface-2: #eceef3; --border: #dde0e8;
  --text: #2d313c; --text-2: #656b7a; --heading: #14161c; --accent: #2a3cff; --accent-ink: #fff; --accent-text: var(--accent);
}
:root[data-style="folio"][data-mode="dark"] {
  --bg: #0f1115; --bg-alt: #0f1115; --surface: #161920; --surface-2: #1d2029; --border: #272b36;
  --text: #b7bdcb; --text-2: #848b9c; --heading: #eceef3; --accent: #8b96ff; --accent-ink: #0b0d1c; --accent-text: var(--accent);
}
[data-style="folio"] body { font-size: 1.02rem; }
[data-style="folio"] h1, [data-style="folio"] h2, [data-style="folio"] h3 { font-weight: 400; letter-spacing: -.01em; }
[data-style="folio"] .hero-name { font-size: clamp(3.4rem, 8vw, 6.4rem); line-height: .95; letter-spacing: -.025em; }
[data-style="folio"] .hero-role { font-family: var(--font-display); font-style: italic; font-weight: 400; font-size: clamp(1.4rem, 3vw, 2rem); color: var(--text); }
[data-style="folio"] .hero { padding-top: clamp(3rem, 8vw, 6rem); }
[data-style="folio"] .hero-inner { grid-template-columns: minmax(0, 1fr); max-width: 980px; gap: 1.4rem; }
[data-style="folio"] .hero-photo { order: -1; justify-self: start; width: 150px; aspect-ratio: 1; border-radius: 50%; margin-bottom: .5rem; }
[data-style="folio"] .hero-photo--mono { font-size: 3rem; background: var(--surface-2); }
[data-style="folio"] .hero-bio { font-size: 1.15rem; max-width: 52ch; color: var(--text); }
[data-style="folio"] .hero-stats dd { font-family: var(--font-display); font-weight: 400; font-size: 2.6rem; }
[data-style="folio"] .btn { border-radius: var(--radius-sm); font-weight: 500; }
[data-style="folio"] .btn--primary { background: var(--heading); border-color: var(--heading); color: var(--bg); }
[data-style="folio"] .btn--primary:hover { color: var(--bg); background: var(--accent-text); border-color: var(--accent-text); }
[data-style="folio"] .badge, [data-style="folio"] .tags li, [data-style="folio"] .chip { border-radius: var(--radius-pill); }
[data-style="folio"] .tags li { background: transparent; border: 1px solid var(--border); color: var(--text-2); font-weight: 500; }
[data-style="folio"] .social { border: 0; background: transparent; width: auto; height: auto; padding: .2rem .35rem; font-size: 1.05rem; color: var(--text-2); }
[data-style="folio"] .social:hover { background: transparent; color: var(--accent-text); }

[data-style="folio"] .section { border-top: 1px solid var(--border); }
[data-style="folio"] .section:nth-of-type(even) { background: transparent; }
@media (min-width: 1100px) {
  [data-style="folio"] .section-inner { display: grid; grid-template-columns: 170px minmax(0, 1fr); gap: 2.5rem; }
}
[data-style="folio"] .sec-title { font-size: 1.7rem; font-style: italic; color: var(--text-2); margin: 0 0 1.6rem; }
@media (min-width: 1100px) { [data-style="folio"] .sec-title { position: sticky; top: 2rem; align-self: start; margin: 0; } }

/* sidebar shell on wide screens */
@media (min-width: 961px) {
  [data-style="folio"] #app { display: grid; grid-template-columns: 290px minmax(0, 1fr); grid-template-rows: auto 1fr; }
  [data-style="folio"] .site-nav { grid-column: 1; grid-row: 1 / span 2; position: sticky; top: 0; height: 100vh; align-self: start; background: var(--bg); border-bottom: 0; border-right: 1px solid var(--border); backdrop-filter: none; }
  [data-style="folio"] main { grid-column: 2; grid-row: 1; min-width: 0; }
  [data-style="folio"] .site-footer { grid-column: 2; grid-row: 2; align-self: end; }
  [data-style="folio"] .nav-inner { flex-direction: column; align-items: flex-start; gap: 2.2rem; padding: 2.4rem 2rem; max-width: none; }
  [data-style="folio"] .brand { flex-direction: column; align-items: flex-start; gap: .9rem; }
  [data-style="folio"] .brand-mark { background: transparent; color: var(--accent-text); border: 1px solid var(--accent-text); border-radius: 50%; width: 2.8rem; height: 2.8rem; font: 400 1.1rem var(--font-display); }
  [data-style="folio"] .brand-name { font: 400 1.7rem/1.05 var(--font-display); letter-spacing: -.01em; }
  [data-style="folio"] .nav-links { flex-direction: column; gap: .3rem; margin: 0; overflow: visible; }
  [data-style="folio"] .nav-links a { font-size: 1rem; color: var(--text-2); padding: .15rem 0; }
  [data-style="folio"] .nav-links a[aria-current] { color: var(--heading); }
  [data-style="folio"] .nav-links a[aria-current]::before { content: '— '; color: var(--accent-text); }
  [data-style="folio"] .nav-tools { margin-top: auto; }
}

[data-style="folio"] .timeline { border: 0; padding: 0; gap: 0; }
[data-style="folio"] .tl-item { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 1.5rem; padding: 1.5rem 0; border-top: 1px solid var(--border); }
[data-style="folio"] .tl-item:first-child { border-top: 0; padding-top: 0; }
[data-style="folio"] .tl-item::before { display: none; }
[data-style="folio"] .tl-head { display: contents; }
[data-style="folio"] .tl-period { grid-column: 1; grid-row: 1; margin: .35rem 0 0; font-size: .85rem; }
[data-style="folio"] .tl-role { grid-column: 2; grid-row: 1; font-size: 1.55rem; }
[data-style="folio"] .tl-org { grid-column: 2; grid-row: 2; margin-top: -.9rem; }
[data-style="folio"] .tl-bullets { grid-column: 2; margin-top: .3rem; }
@media (max-width: 600px) { [data-style="folio"] .tl-item { grid-template-columns: 1fr; gap: .4rem; } [data-style="folio"] .tl-period, [data-style="folio"] .tl-role, [data-style="folio"] .tl-org, [data-style="folio"] .tl-bullets { grid-column: 1; grid-row: auto; margin-top: 0; } }
[data-style="folio"] .proj-card, [data-style="folio"] .edu-item, [data-style="folio"] .cert-card, [data-style="folio"] .award, [data-style="folio"] .link-card, [data-style="folio"] .pub, [data-style="folio"] .contact-form { box-shadow: none; }
[data-style="folio"] .proj-img img { filter: grayscale(.7); transition: filter .3s; }
[data-style="folio"] .proj-card:hover .proj-img img { filter: none; }
[data-style="folio"] .proj-body h3 { font-size: 1.6rem; }
[data-style="folio"] .link-icon, [data-style="folio"] .ci-icon { background: transparent; border: 1px solid var(--border); }
[data-style="folio"] .pub-year { font-family: var(--font-display); font-weight: 400; font-size: 1.3rem; }
[data-style="folio"] .tl-role, [data-style="folio"] .edu-info h3 { font-weight: 400; }

/* Brutal — thick outlines, hard shadows, flat colour */
:root[data-style="brutal"] {
  --font-display: 'Space Grotesk', system-ui, sans-serif; --font-body: 'Space Grotesk', system-ui, sans-serif; --font-mono: 'Space Mono', ui-monospace, monospace;
  --radius: 0px; --radius-sm: 0px; --radius-pill: 0px; --card-pad: 1.3rem; --bw: 3px;
}
:root[data-style="brutal"][data-mode="light"] {
  --bg: #fffdf5; --bg-alt: color-mix(in srgb, var(--accent) 42%, #fffdf5); --surface: #ffffff; --surface-2: #f1eedf; --border: #111111;
  --ink: #111111; --text: #1b1b1b; --text-2: #3d3d3d; --heading: #111111; --accent: #ffd23f; --accent-ink: #111111; --accent-text: #111111; --shadow-c: #111111;
}
:root[data-style="brutal"][data-mode="dark"] {
  --bg: #121212; --bg-alt: #1d1d1d; --surface: #1c1c1c; --surface-2: #262626; --border: #fffdf5;
  --ink: #fffdf5; --text: #e9e6da; --text-2: #bdb9aa; --heading: #fffdf5; --accent: #ffd23f; --accent-ink: #111111; --accent-text: #ffd23f; --shadow-c: #ffd23f;
}
[data-style="brutal"] body { font-weight: 500; }
[data-style="brutal"] a { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 3px; }
[data-style="brutal"] .site-nav { background: var(--bg); backdrop-filter: none; border-bottom: var(--bw) solid var(--border); }
[data-style="brutal"] .brand-mark { border: var(--bw) solid var(--border); color: var(--accent-ink); }
[data-style="brutal"] .brand, [data-style="brutal"] .nav-links a, [data-style="brutal"] .btn-link, [data-style="brutal"] .social, [data-style="brutal"] .btn { text-decoration: none; }
[data-style="brutal"] .nav-links a { color: var(--heading); font-weight: 700; font-size: .9rem; padding: .2rem .35rem; }
[data-style="brutal"] .nav-links a:hover, [data-style="brutal"] .nav-links a[aria-current] { background: var(--accent); color: var(--accent-ink); }
[data-style="brutal"] .btn, [data-style="brutal"] .icon-btn, [data-style="brutal"] .social { border: var(--bw) solid var(--border); background: var(--surface); color: var(--heading); box-shadow: 4px 4px 0 var(--shadow-c); font-weight: 700; transition: transform .1s, box-shadow .1s; }
[data-style="brutal"] .btn:hover, [data-style="brutal"] .icon-btn:hover, [data-style="brutal"] .social:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--shadow-c); background: var(--accent); color: var(--accent-ink); border-color: var(--border); filter: none; }
[data-style="brutal"] .btn:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--shadow-c); }
[data-style="brutal"] .btn--primary { background: var(--accent); color: var(--accent-ink); }
[data-style="brutal"] .btn--primary:hover { background: var(--surface); color: var(--heading); }
[data-style="brutal"] .btn--small { box-shadow: 3px 3px 0 var(--shadow-c); }

[data-style="brutal"] .hero { border-bottom: var(--bw) solid var(--border); }
[data-style="brutal"] .hero-name { font-size: clamp(3rem, 9vw, 7rem); font-weight: 700; line-height: .95; letter-spacing: -.04em; }
[data-style="brutal"] .hero-kicker { display: inline-block; padding: .2rem .6rem; border: var(--bw) solid var(--border); background: var(--surface); color: var(--heading); font-family: var(--font-mono); font-size: .8rem; }
[data-style="brutal"] .hero-kicker i { color: var(--heading); }
[data-style="brutal"] .hero-role { display: inline-block; margin-top: 1.1rem; padding: .3rem .8rem; background: var(--accent); color: var(--accent-ink); font-family: var(--font-mono); font-size: 1.05rem; font-weight: 700; border: var(--bw) solid var(--border); }
[data-style="brutal"] .hero-bio { color: var(--text); font-size: 1.15rem; }
[data-style="brutal"] .hero-photo { border: var(--bw) solid var(--border); box-shadow: 10px 10px 0 var(--shadow-c); transform: rotate(2.5deg); background: var(--accent); }
[data-style="brutal"] .hero-photo--mono { color: var(--accent-ink); }
[data-style="brutal"] .badge, [data-style="brutal"] .chip, [data-style="brutal"] .tags li { border: 2px solid var(--border); background: var(--surface); color: var(--heading); font-weight: 700; }
[data-style="brutal"] .badge { font-family: var(--font-mono); }
[data-style="brutal"] .tags li { background: var(--accent); color: var(--accent-ink); border-radius: 0; }
[data-style="brutal"] .chip i { color: var(--heading); }
